// src/components/Navbar.jsx
import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useTheme } from "../context/ThemeContext";

const Navbar = () => {
  const { colors, toggleTheme, theme } = useTheme();
  const navigate = useNavigate();

  const [isAuth, setIsAuth] = useState(false);
  const [email, setEmail] = useState("");
  const [role, setRole] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("access");
    const userEmail = localStorage.getItem("userEmail");
    const userRole = localStorage.getItem("userRole");

    setIsAuth(!!token);
    setEmail(userEmail || "");
    setRole(userRole);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("access");
    localStorage.removeItem("refresh");
    localStorage.removeItem("userEmail");
    localStorage.removeItem("userRole");

    setIsAuth(false);
    navigate("/login");
  };

  return (
    <nav
      style={{
        backgroundColor: colors.navbarBg,
        padding: "16px 32px",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
      }}
    >
      {/* LOGO */}
      <Link
        to="/"
        style={{
          fontWeight: 700,
          fontSize: "18px",
          color: colors.primary,
          textDecoration: "none",
        }}
      >
        THESIS CHECK
      </Link>

      {/* LINKS */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "18px",
        }}
      >
        <Link to="/" style={linkStyle(colors)}>Home</Link>
        <Link to="/about" style={linkStyle(colors)}>About</Link>
        <Link to="/contact" style={linkStyle(colors)}>Contact</Link>

        {/* ROLE-BASED LINKS */}
        {role === "student" && (
          <>
            <Link to="/dashboard" style={linkStyle(colors)}>
              Dashboard
            </Link>
            <Link to="/upload" style={linkStyle(colors)}>
              Upload Thesis
            </Link>
          </>
        )}

        {role === "advisor" && (
          <Link to="/advisor" style={linkStyle(colors)}>
            Advisor
          </Link>
        )}

        {role === "admin" && (
          <Link to="/admin" style={linkStyle(colors)}>
            Admin
          </Link>
        )}

        {/* THEME TOGGLE */}
        <button onClick={toggleTheme} style={themeButton(colors)}>
          {theme === "dark" ? "🌞 Light" : "🌙 Dark"}
        </button>

        {/* AUTH */}
        {!isAuth ? (
          <Link to="/login" style={loginButton(colors)}>
            LOG IN
          </Link>
        ) : (
          <>
            <span style={{ fontSize: "13px", opacity: 0.85 }}>
              {email}
            </span>
            <button onClick={handleLogout} style={logoutButton(colors)}>
              LOG OUT
            </button>
          </>
        )}
      </div>
    </nav>
  );
};

const linkStyle = (colors) => ({
  color: colors.text,
  textDecoration: "none",
  fontSize: "14px",
  fontWeight: 500,
});

const loginButton = (colors) => ({
  color: colors.primary,
  textDecoration: "none",
  fontWeight: 600,
});

const logoutButton = (colors) => ({
  background: "transparent",
  border: `1px solid ${colors.primary}`,
  color: colors.primary,
  padding: "6px 14px",
  borderRadius: "999px",
  cursor: "pointer",
  fontWeight: 600,
});

const themeButton = (colors) => ({
  background: "transparent",
  border: `1px solid ${colors.text}40`,
  color: colors.text,
  padding: "6px 12px",
  borderRadius: "999px",
  cursor: "pointer",
});

export default Navbar;
